#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: the human steps of ticket 71 (spec 385), one phase per run. The agent's steps sit between them, so run a
# phase only when the agent asks for it:
#
#   bash scripts/backend-wizard.sh h1   Cloudflare account: 2FA, card and R2, Zero Trust, budget alert, billing, id
#   bash scripts/backend-wizard.sh h2   Tokens: Wrangler login, the CI token, the GitHub production environment
#   bash scripts/backend-wizard.sh h3   Access, Google, Turnstile, UptimeRobot, Healthchecks.io, analytics token
#   bash scripts/backend-wizard.sh h4   The backup's age key pair
#   bash scripts/backend-wizard.sh h5   Removing the Flint 2 deploy's secrets and keys; the last billing check
#
# No secret is ever typed into the chat, a file or a log. A secret goes from your keyboard straight to its owner:
# `wrangler secret put` (Cloudflare) or `gh secret set` (GitHub), each of which asks for it hidden. Only ids, site
# keys, host names and the age public key (none secret) are saved, in backend-handoff.local (gitignored), for the
# agent to read.
# ──────────────────────────────────────────────────────────────────────────

# Always from the repo root, wherever it is started: Wrangler needs wrangler.jsonc, gh picks the repo from the
# folder's git remote (H2's GitHub stage once ran elsewhere and set nothing), and the handoff file lives here.
cd "$(dirname "$0")/.." || exit 1
ENV_FILE="${BACKEND_HANDOFF:-backend-handoff.local}"
# Provisional: ticket 78 owns the final path, and the Google console lets you edit the URIs later.
GOOGLE_CALLBACK_PATH="/api/auth/google/callback"

# ask_host KEY PROMPT: like ask, but keeps the bare host, so "https://x.workers.dev/" and "x.workers.dev" both give
# x.workers.dev. Every later stage adds the scheme itself where it needs one.
ask_host() {
  ask "$1" "$2"
  local host="${!1#*://}"
  printf -v "$1" '%s' "${host%%/*}"
}

# put_secret NAME ENV: wrangler asks for the value itself, hidden, and sends it straight to Cloudflare.
put_secret() {
  say "Wrangler asks for $1 for the $2 Worker. Paste it there: it is hidden and goes straight to Cloudflare."
  npx wrangler secret put "$1" --env "$2" || {
    warn "wrangler could not set $1 for $2 (is the Worker deployed, and are you logged in?)"
    SKIPPED+=("Cloudflare secret $1 for $2: npx wrangler secret put $1 --env $2")
  }
}
put_secret_both() { put_secret "$1" dev; put_secret "$1" production; }

# gh_env_secret NAME: gh asks for the value itself, hidden, and stores it in the production environment.
gh_env_secret() {
  say "gh asks for $1. Paste it there: it is hidden and goes straight to GitHub."
  if gh secret set "$1" --env production; then
    WRITTEN_SECRET+=("$1 (production environment)")
  else
    warn "gh could not set $1"
    SKIPPED+=("GitHub environment secret $1: gh secret set $1 --env production")
  fi
}
gh_env_var() {
  if gh variable set "$1" --env production --body "$2" >/dev/null; then
    printf '  %s✓ set%s GitHub variable %s (production environment)\n' "$GREEN" "$RESET" "$1"
  else
    warn "gh could not set $1"
    SKIPPED+=("GitHub environment variable $1: gh variable set $1 --env production --body <value>")
  fi
}

need_gh() {
  command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 || {
    warn "This phase needs the GitHub CLI, logged in: run 'gh auth login' first."
    exit 1
  }
}

phase_h1() {
  stage "Cloudflare: two-factor sign-in"
  say "A stolen login could bill you or empty the account, so this comes first."
  open_url "https://dash.cloudflare.com/profile/authentication"
  step "Turn on two-factor authentication (an authenticator app or a security key)."
  step "Save the recovery codes in your password manager."
  pause "Two-factor is on? Press Enter."

  stage "Cloudflare: the card and R2"
  say "R2 needs a card on file even inside its free allowance. Nothing is charged inside it."
  open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
  step "Add the card if it asks (Billing → Payment info), then enable R2."
  step "Do NOT add any paid add-on, and do not choose Workers Paid."
  note "The wording of these pages changes; the point is R2 enabled and nothing paid."
  pause "R2 is enabled? Press Enter."

  stage "Cloudflare: Zero Trust (Access)"
  say "Access puts a sign-in in front of both Workers until the public release."
  open_url "https://one.dash.cloudflare.com/"
  step "Choose a team name (it becomes <team>.cloudflareaccess.com) and the Free plan."
  if confirm "Did Zero Trust ask for the card?"; then write_env ZERO_TRUST_ASKED_FOR_CARD yes; else write_env ZERO_TRUST_ASKED_FOR_CARD no; fi
  ask CF_ACCESS_TEAM_NAME "Your team name:"
  write_env CF_ACCESS_TEAM_NAME "$CF_ACCESS_TEAM_NAME"

  stage "Cloudflare: a budget alert at \$1"
  say "Cloudflare has no spending cap; a budget alert emails you the day after projected spend passes it."
  open_url "https://dash.cloudflare.com/?to=/:account/notifications"
  step "Add → look for a Billing / Budget alert. If there is one, set it at \$1, by email to you."
  note "It may only be offered to pay-as-you-go accounts. If it isn't there, that's the answer: say no below."
  if confirm "Was a budget alert offered, and did you set it?"; then write_env BUDGET_ALERT set; else write_env BUDGET_ALERT not-offered; fi

  stage "Cloudflare: billing check"
  open_url "https://dash.cloudflare.com/?to=/:account/billing/subscriptions"
  step "Billing → Subscriptions must list nothing paid. If anything is, cancel it."
  confirm "Does it show no paid subscription?" || { warn "Fix this before going on, then re-run this phase."; exit 1; }

  stage "Cloudflare: the account id"
  say "The account id is not a secret; the agent needs it to create the databases and buckets."
  open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
  step "Copy the Account ID from the right-hand column."
  ask CLOUDFLARE_ACCOUNT_ID "Paste the account id:"
  write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  say "Tell the agent: \"H1 done\". The values are in $ENV_FILE."
}

phase_h2() {
  need_gh
  stage "Wrangler: log in on this machine"
  say "This lets the agent create the databases and buckets from here. The login stays on this machine."
  say "Run this on the machine the agent works on. If it has no browser, first run on the machine with the browser:"
  say "  ssh -N -L 8976:localhost:8976 <user>@<this machine>"
  say "so Cloudflare's redirect to localhost:8976 reaches this machine."
  step "Open the URL Wrangler prints, and allow Wrangler."
  npx wrangler login --browser=false
  npx wrangler whoami

  stage "Cloudflare: the CI token"
  say "CI deploys with this token. It must reach this account only, and only Workers Scripts and D1."
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → Create Custom Token. Name it bd-beads-ci."
  step "Permissions: Account → Workers Scripts → Edit; Account → D1 → Edit. Nothing else."
  step "Account Resources: Include → this one account only."
  step "Create it and keep its page open: the next stage asks for it."
  pause "Token created and visible? Press Enter."

  stage "GitHub: the production environment"
  say "The token and the account id live only in the 'production' environment, limited to main, so no branch,"
  say "pull request or fork can deploy."
  if gh api "repos/{owner}/{repo}/environments/production" >/dev/null 2>&1; then
    note "The 'production' environment exists. Check below that it is limited to main."
  elif confirm "Create the 'production' environment now, limited to the main branch?"; then
    gh api -X PUT "repos/{owner}/{repo}/environments/production" \
      -F 'deployment_branch_policy[protected_branches]=false' -F 'deployment_branch_policy[custom_branch_policies]=true' >/dev/null
    gh api -X POST "repos/{owner}/{repo}/environments/production/deployment-branch-policies" -f name=main >/dev/null
    printf '  %s✓ created%s the production environment, main only\n' "$GREEN" "$RESET"
  fi
  open_url "https://github.com/$(gh repo view --json nameWithOwner -q .nameWithOwner)/settings/environments"
  step "Open production: Deployment branches and tags must say Selected branches → main."
  pause "Limited to main? Press Enter."

  stage "GitHub: the token and the account id"
  gh_env_secret CLOUDFLARE_API_TOKEN
  ask CLOUDFLARE_ACCOUNT_ID "Account id (from phase h1):"
  write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  gh_env_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  say "Tell the agent: \"H2 done\"."
}

phase_h3() {
  need_gh
  stage "The two Worker addresses"
  say "The agent deployed both Workers in step A2 and gave you their workers.dev addresses."
  ask_host WORKER_HOST_DEV "Dev host (bd-beads-dev.<subdomain>.workers.dev):"
  ask_host WORKER_HOST_PRODUCTION "Production host (bd-beads.<subdomain>.workers.dev):"
  write_env WORKER_HOST_DEV "$WORKER_HOST_DEV"
  write_env WORKER_HOST_PRODUCTION "$WORKER_HOST_PRODUCTION"

  stage "Access (H3a): both Workers behind a sign-in"
  open_url "https://one.dash.cloudflare.com/"
  step "Once: Integrations → Identity providers → Add new → One-time PIN. Nothing to fill in; save."
  step "Access controls → Applications → Add an application → Self-hosted. Four applications in all:"
  step "  per host, one that asks for a sign-in, and one that lets /api/health through."
  note "workers.dev isn't one of your domains, so the Domain list is empty: click 'Switch to custom input' and type"
  note "the host, without https://."
  step "Sign-in application, host $WORKER_HOST_DEV, Path empty:"
  step "  policy Allow, include Emails: yours, then each tester's;"
  step "  Authentication: tick One-time PIN only (refresh the page if it isn't listed)."
  step "Health application, same host, Path api/health: policy Bypass, include Everyone."
  step "The same two for $WORKER_HOST_PRODUCTION (pick the policies under 'Add current policies')."
  note "The more specific path wins: health answers without a sign-in, and nothing else does."
  step "Open each host in a private window: you get the Access sign-in, and /api/health answers."
  confirm "Does it behave like that on both hosts?" || warn "Not confirmed: fix it before telling the agent."

  stage "Google (H3b): the project and the consent screen"
  open_url "https://console.cloud.google.com/projectcreate"
  step "Create a project named bd-beads."
  open_url "https://console.cloud.google.com/auth/overview"
  note "The consent screen is what Google shows someone signing in to the app (not Access) with Google."
  step "Get started (or Branding): app name bd-beads, your email as support and contact, audience External."
  step "Audience: publishing status stays Testing (don't publish). Test users → Add users: yours (and testers')."
  step "Data access → Add or remove scopes: tick only openid, .../auth/userinfo.email and .../auth/userinfo.profile."
  step "Update, then Save. Both sensitive-scope tables stay empty."
  pause "Consent screen done, in Testing? Press Enter."

  stage "Google (H3b): the OAuth client"
  open_url "https://console.cloud.google.com/auth/clients/create"
  step "Application type: Web application. Name: bd-beads."
  say "Authorized redirect URIs, for now the two localhost ones. Google refuses workers.dev (it's on the Public Suffix"
  say "List); phase h6 adds the custom domains' two:"
  say "  http://localhost:5173$GOOGLE_CALLBACK_PATH"
  say "  http://localhost:8787$GOOGLE_CALLBACK_PATH"
  ask GOOGLE_CLIENT_ID "Paste the client id (not secret):"
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  step "Copy the client secret from the same page; wrangler asks for it next, twice (dev, then production)."
  put_secret_both GOOGLE_CLIENT_SECRET

  stage "Turnstile (H3c)"
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
  step "Add widget, name bd-beads. Hostnames, typed one by one with Enter after each (the list shows only your domains):"
  step "  $WORKER_HOST_DEV, $WORKER_HOST_PRODUCTION and localhost (skip localhost if refused: tests use dummy keys)."
  note "Phase h6 adds the custom domains' two hostnames."
  step "Widget mode: Managed. Pre-clearance: no."
  ask TURNSTILE_SITE_KEY "Paste the site key (not secret):"
  write_env TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY"
  step "Copy the secret key; wrangler asks for it next, twice."
  put_secret_both TURNSTILE_SECRET_KEY

  stage "UptimeRobot (H3d)"
  open_url "https://dashboard.uptimerobot.com/monitors"
  step "Sign in with the account whose inbox gets the alerts. Add two HTTP(s) monitors, interval 15 minutes:"
  step "  https://$WORKER_HOST_DEV/api/health and https://$WORKER_HOST_PRODUCTION/api/health"
  step "Alert contacts: your email, and the UptimeRobot phone app (install it and sign in; it sends the push)."
  pause "Both monitors are up and green? Press Enter."

  stage "Healthchecks.io (H3d): three checks, email only"
  open_url "https://healthchecks.io/accounts/signup/"
  step "Sign up or log in: you land in your default project's checks."
  step "Add Check three times, schedule Simple, each alerting by email to you:"
  step "  watchdog-dev: period 15 minutes, grace 1 hour"
  step "  watchdog-production: period 15 minutes, grace 1 hour"
  step "  backup-weekly: period 7 days, grace 1 day"
  say "The ping URLs (https://hc-ping.com/<uuid>, on each check's page) are secrets. Wrangler asks for"
  say "watchdog-dev's, then watchdog-production's;"
  say "gh then asks for backup-weekly's."
  put_secret HEALTHCHECK_URL dev
  put_secret HEALTHCHECK_URL production
  gh_env_secret HEALTHCHECK_BACKUP_URL

  stage "Cloudflare (H3d): the analytics token"
  say "The watchdog reads today's usage with a read-only token."
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Custom Token, name bd-beads-analytics: Account → Account Analytics → Read. Nothing else."
  step "Account Resources: this one account only. Wrangler asks for it next, twice."
  put_secret_both CF_ANALYTICS_TOKEN
  say "Tell the agent: \"H3 done\". The ids, hosts and site key are in $ENV_FILE."
}

phase_h4() {
  need_gh
  stage "age: the backup's key pair, on your own computer"
  say "The weekly backup is encrypted to this key. The private key stays with you, never on GitHub."
  step "Install age if needed, then run: age-keygen -o bd-beads-backup.key"
  step "Put that file's contents in your password manager, then delete the file."
  step "The line starting 'Public key: age1…' is the public key; it is not secret."
  ask AGE_PUBLIC_KEY "Paste the public key (age1...):"
  [[ "$AGE_PUBLIC_KEY" == age1* ]] || { warn "That doesn't look like an age public key; re-run this phase."; exit 1; }
  write_env AGE_PUBLIC_KEY "$AGE_PUBLIC_KEY"
  gh_env_var AGE_PUBLIC_KEY "$AGE_PUBLIC_KEY"
  say "Tell the agent: \"H4 done\"."
}

phase_h5() {
  need_gh
  stage "GitHub: the Flint 2 deploy's secrets and variables"
  say "The Flint 2 deploy is gone (step A5), and so are its credentials."
  for name in DEPLOY_HOST DEPLOY_USER DEPLOY_SSH_KEY DEPLOY_KNOWN_HOSTS TS_OAUTH_CLIENT_ID TS_OAUTH_SECRET; do
    if confirm "Delete the GitHub secret $name?"; then gh secret delete "$name" || warn "$name: not found or not deleted"; fi
  done
  for name in DEPLOY_PATH DEPLOY_BASE; do
    if confirm "Delete the GitHub variable $name?"; then gh variable delete "$name" || warn "$name: not found or not deleted"; fi
  done

  stage "Tailscale: the CI client and its tag"
  open_url "https://login.tailscale.com/admin/settings/oauth"
  step "Revoke the OAuth client CI used."
  open_url "https://login.tailscale.com/admin/acls/file"
  step "Remove tag:ci from tagOwners and from every rule that names it; save."
  pause "Done? Press Enter."

  stage "The router: the deploy key"
  step "ssh to the Flint 2 and edit /etc/dropbear/authorized_keys: delete the CI deploy key's line, keep your own."
  pause "Done? Press Enter."

  stage "Cloudflare: billing, once more"
  open_url "https://dash.cloudflare.com/?to=/:account/billing/subscriptions"
  step "Billing → Subscriptions must list nothing paid."
  confirm "Does it show no paid subscription?" || { warn "Cancel it before the release, then re-run this phase."; exit 1; }
  say "Tell the agent: \"H5 done\"."
}

phase_h6() {
  need_gh
  stage "The domain's two hostnames (ticket 400)"
  say "Production answers at the domain's apex and dev at dev.<domain>; the workers.dev addresses stay on beside them."
  ask_host DOMAIN_PRODUCTION "Production host (the apex you bought, e.g. openbeads.com):"
  ask_host DOMAIN_DEV "Dev host (dev.<the apex>):"
  write_env DOMAIN_PRODUCTION "$DOMAIN_PRODUCTION"
  write_env DOMAIN_DEV "$DOMAIN_DEV"
  say "The agent puts both in wrangler.jsonc (routes, and PUBLIC_ORIGIN) and deploys; wrangler makes the DNS records."
  confirm "Is the deploy with the routes done?" || { warn "Ask the agent to deploy first, then re-run this phase."; exit 1; }

  stage "Cloudflare: auto-renew, and the www redirect"
  open_url "https://dash.cloudflare.com/?to=/:account/domains/registrations"
  step "The domain's auto-renew is on. Write its renewal price in the ticket."
  open_url "https://dash.cloudflare.com/?to=/:account/:zone/rules/redirect-rules"
  step "A redirect from www.$DOMAIN_PRODUCTION (any path) to https://$DOMAIN_PRODUCTION, status 301."
  note "The www record needs an AAAA 100:: record, proxied, to be reached; add it under DNS if the rule alone does nothing."

  stage "Access: a sign-in application for each hostname"
  open_url "https://one.dash.cloudflare.com/"
  step "Access controls → Applications → Add an application → Self-hosted, for $DOMAIN_PRODUCTION and $DOMAIN_DEV."
  step "Each: policy Allow, include Emails: yours, then each tester's; Authentication: One-time PIN only."
  step "Production's only: a second application, same host, Path api/health, policy Bypass, include Everyone."
  step "Dev's has no health bypass (ticket 395)."
  ask ACCESS_AUD_DEV "Dev's application: its Audience tag (Overview tab; not secret, it differs per application):"
  write_env ACCESS_AUD_DEV "$ACCESS_AUD_DEV"
  step "In a private window, both hostnames show the Access sign-in."

  stage "Google: the domain, and the two callbacks"
  open_url "https://console.cloud.google.com/auth/branding"
  step "Authorized domains: add $DOMAIN_PRODUCTION (one covers dev.). Save. The consent screen stays in Testing."
  open_url "https://console.cloud.google.com/auth/clients"
  step "Open the bd-beads client. Authorized JavaScript origins: https://$DOMAIN_PRODUCTION and https://$DOMAIN_DEV."
  say "Authorized redirect URIs, beside the two localhost ones:"
  say "  https://$DOMAIN_PRODUCTION$GOOGLE_CALLBACK_PATH"
  say "  https://$DOMAIN_DEV$GOOGLE_CALLBACK_PATH"
  step "Save. Each tester is a test user (Audience → Test users)."
  pause "Saved? Press Enter."

  stage "Turnstile"
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
  step "The bd-beads widget's hostnames: add $DOMAIN_PRODUCTION and $DOMAIN_DEV."
  note "The Google client secret and the Turnstile secret are already the Workers' secrets (phase h3); nothing to paste."
  say "Tell the agent: \"H6 done\" and give it the dev audience tag from $ENV_FILE."
}

case "${1:-}" in
  h1) TOTAL_STAGES=6; banner "Backend H1: the Cloudflare account"; phase_h1 ;;
  h2) TOTAL_STAGES=4; banner "Backend H2: tokens"; phase_h2 ;;
  h3) TOTAL_STAGES=8; banner "Backend H3: sign-in, bots and alerts"; phase_h3 ;;
  h4) TOTAL_STAGES=1; banner "Backend H4: the backup's key"; phase_h4 ;;
  h5) TOTAL_STAGES=4; banner "Backend H5: the old deploy's credentials, and billing"; phase_h5 ;;
  h6) TOTAL_STAGES=5; banner "Backend H6: the domain on both Workers, and Google sign-in"; phase_h6 ;;
  *) echo "Usage: bash scripts/backend-wizard.sh h1|h2|h3|h4|h5|h6   (ticket 71's human steps, in order)"; exit 2 ;;
esac

finish
